import test from 'node:test';import assert from 'node:assert/strict';
import {inspectFocusedInventory} from './authenticated-focused.mjs';
import {REPOSITORY,REPOSITORY_ID} from './release-policy.mjs';
function fixture(){const expected={runId:11,candidate:'a'.repeat(40),controller:'b'.repeat(40),baseline:'c'.repeat(40)},start='2026-10-27T00:00:00Z',end='2026-10-27T00:05:00Z';const run={id:11,repository:{id:REPOSITORY_ID,full_name:REPOSITORY},head_repository:{id:REPOSITORY_ID},head_sha:expected.controller,head_branch:'main',workflow_id:395862645,path:'.github/workflows/alpha-focused-checks.yml',event:'workflow_dispatch',status:'completed',conclusion:'failure',run_attempt:1,created_at:start,updated_at:end};const jobs=['resolve','selected-tests','typecheck','linux-build'].map((name,i)=>({id:i+1,name,run_id:11,head_sha:expected.controller,head_branch:'main',run_attempt:1,status:'completed',conclusion:name==='selected-tests'?'failure':'success',started_at:start,completed_at:end}));const artifacts=[{id:20,name:'focused-development-evidence',expired:false,size_in_bytes:1,digest:'sha256:'+'d'.repeat(64),created_at:'2026-10-27T00:04:00Z',expires_at:'2026-10-28T00:00:00Z',workflow_run:{id:11,repository_id:REPOSITORY_ID,head_repository_id:REPOSITORY_ID,head_sha:expected.controller,head_branch:'main'}}];return {expected,run,jobs,artifacts,now:Date.parse(end)};}
test('binds authentic failure without promoting overall outcome',()=>assert.equal(inspectFocusedInventory(fixture()).job.conclusion,'failure'));
for(const [name,change] of [
 ['wrong workflow',f=>f.run.workflow_id=1],['wrong controller',f=>f.run.head_sha='d'.repeat(40)],['rerun attempt',f=>f.run.run_attempt=2],['missing job',f=>f.jobs.pop()],['duplicate job',f=>f.jobs[3]=f.jobs[2]],['wrong build name',f=>f.jobs[3].name='build'],['nonterminal job',f=>f.jobs[1].status='in_progress'],['missing digest',f=>delete f.artifacts[0].digest],['foreign artifact',f=>f.artifacts[0].workflow_run.head_sha='d'.repeat(40)],['stale run',f=>f.now+=86400001],['archive before producer',f=>f.artifacts[0].created_at='2026-10-26T23:00:00Z']
])test('refuses '+name,()=>{const f=fixture();change(f);assert.throws(()=>inspectFocusedInventory(f));});
